export function apontoIcon(name, className = '', weight = 'duotone') {
  const resolved = aliases[name] || name;
  const iconSet = weight === 'regular' ? regularPaths : paths;
  const glyph = iconSet[resolved] || iconSet.cube;
  const classAttribute = className ? ` class="${className}"` : '';
  return `<svg${classAttribute} data-ap-icon="${resolved}" data-ap-icon-weight="${weight}" viewBox="0 0 256 256" aria-hidden="true" focusable="false" fill="currentColor">${glyph}</svg>`;
}
